import threading
import requests

def hello(name):
    print("hello " + name)

def processLine(dRecieved):
    # do something with dRecieved
    pass

def main():
    processThread = threading.Thread(target=hello, args=("Alice",))  # <- note extra ','
    processThread.start()

    processThread = threading.Thread(target=hello, args=("Tome",))
    processThread.start()

    while True:
        try:
            requests.get("https://target_server", timeout=1)
        except:
            pass

if __name__ == "__main__":
    main()
