        print("Monday Count:", self.count_mon)
        self.sum_mon = list(map(add, self.sum_mon, curr_mon))  #Adds all the Mondays together for each hour
        print("Total sum of all Mondays::", self.sum_mon)
        self.avg_mon = list(map(lambda w_mon: float(w_mon)/self.count_mon, self.sum_mon))  #Gets the average of the Mondays for each hour
        print("Average Monday::", self.avg_mon)

    def __getitem__(self, item):
        if isinstance(item, int):
            return self.sum_mon[item]
        else:
            return self.sum_mon

    def __len__(self):
        return len(self.sum_mon)

    def __getattr__(self, name):
        if name == "__len__":
            return len(self.sum_mon)
        elif name == "__getitem__":
            return self.sum_mon
        else:
            raise AttributeError("'Week' object has no attribute '{}'".format(name))
