import multiprocessing
import time
from multiprocessing import Manager, Queue

def f(queue):
    list = []
    while True:
        i = "x" * 1000000
        list.append(i)
        time.sleep(1)
        queue.put("Worker %d is done" % len(list))

def worker(name, queue):
    while True:
        time.sleep(1)
        queue.put("%d is done" % name)

if __name__ == '__main__':
    m = Manager()
    queue = m.Queue()
    pool = multiprocessing.Pool(processes=3)
    workers = pool.map(worker, range(3))
    for w in workers:
        w.put(("worker1", queue))
    for w in workers:
        w.put(("worker2", queue))
    for w in workers:
        w.put(("worker3", queue))
    for _ in range(5):
        data = queue.get()
        if data:
            print(data)
    while not queue.empty():
        if queue.empty():
            break
        print(queue.get())
```

