import numpy as np
import math
import socket

def newtonRaphson2(f, x, h=1e-9, max_iter=1000):
    x_new = x - h * (f(x) - 0.5 * f(x - h))
    if abs(f(x_new)) < 1e-6:
        return x_new
    else:
        return newtonRaphson2(f, x_new, h, max_iter)

def test():
    a = (np.arange(10) - 1).tolist()
    rslt = []
    for i in a:
        x = newtonRaphson2(lambda x: math.log(x), i)
        rslt.append(x)

    return rslt
