import numpy as np
import math
import psutil

def test():
    a = (np.arange(10) - 1).tolist()
    rslt = []
    for i in a:
        if i >= 0:
            rslt.append(math.log(i))

    return rslt

def newtonRaphson2(x, f, tol=1e-9):
    x_new = x
    m = 1
    while True:
        f_x = f(x_new)
        d = f_x - f(x)
        if d < 0:
            x_new = x - d / (f(x) - f(x_new))
        else:
            x_new = x_new - d / f(x_new)
        if abs(x_new - x) < tol:
            break
        x = x_new

    return x

if __name__ == '__main__':
    test()
    x = newtonRaphson2(0, lambda x: math.log(x))
    print(x)
